const raw = $input.first().json || {};
const headers = raw.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const expected = $env.N8N_CALENDAR_TOKEN;

if (!expected || auth !== `Bearer ${expected}`) {
  throw new Error('AUTH_FAILED: Bearer token required for raw cancel writer');
}

const payload = raw.body || raw;
let rawRes = payload.resources;
if (typeof rawRes === 'string') {
  try { rawRes = JSON.parse(rawRes); } catch (e) { rawRes = rawRes.split(',').map(s => s.trim()); }
}
if (!Array.isArray(rawRes) || rawRes.length === 0) {
  throw new Error('RECURSOS_INVALIDOS: resources es obligatorio y debe ser un array no vacio de "calendar" y/o "zoom".');
}
const validSet = new Set(['calendar', 'zoom']);
for (const r of rawRes) {
  if (!validSet.has(r)) {
    throw new Error(`RECURSOS_INVALIDOS: recurso desconocido "${r}". Solo se permite "calendar" y/o "zoom".`);
  }
}
const unique = Array.from(new Set(rawRes));
const resources = ['calendar', 'zoom'].filter(r => unique.includes(r));
if (resources.length === 0) {
  throw new Error('RECURSOS_INVALIDOS: resources no contiene recursos validos.');
}

const needCalendar = resources.includes('calendar');
const needZoom = resources.includes('zoom');

const calendarEventId = String(payload.calendarEventId || payload.event_id || '').trim();
const zoomMeetingId = String(payload.zoomMeetingId || payload.zoom_id || '').trim();
const calendarId = payload.calendarId || 'ocompudoc@gmail.com';

if (needCalendar && !calendarEventId) {
  throw new Error('MISSING_CALENDAR_EVENT_ID: calendarEventId es obligatorio para cancelar recurso calendar.');
}
if (needZoom && !zoomMeetingId) {
  throw new Error('MISSING_ZOOM_MEETING_ID: zoomMeetingId es obligatorio para cancelar recurso zoom.');
}

return [{ json: { ...payload, resources, needCalendar, needZoom, calendarEventId, zoomMeetingId, calendarId } }];

const norm = $('Normalize Cancel').first().json;
const resources = norm.resources || [];
const needCalendar = resources.includes('calendar');
const needZoom = resources.includes('zoom');

const components = {};
let allVerified = true;

if (needZoom) {
  let zoomDelResp = null;
  try { zoomDelResp = $('Delete Zoom Meeting').first()?.json; } catch (e) {}
  const zoomError = zoomDelResp?.error?.message || zoomDelResp?.error || null;
  const isZoomDeleted = !zoomError && (zoomDelResp?.success !== false);

  if (isZoomDeleted) {
    components.zoom = {
      state: 'verified',
      id: norm.zoomMeetingId
    };
  } else {
    allVerified = false;
    components.zoom = {
      state: 'failed',
      id: norm.zoomMeetingId,
      error: zoomError || 'Zoom meeting deletion failed'
    };
  }
}

if (needCalendar) {
  let getResp = null;
  try { getResp = $('Verify Event Absence in Calendar').first()?.json; } catch (e) {}
  const statusCode = Number(getResp?.statusCode || (getResp?.status === 404 || getResp?.status === 410 ? getResp.status : 0));
  const body = getResp?.body || getResp || {};
  const isAbsent = statusCode === 404 || statusCode === 410 || body.status === 'cancelled' || body.error?.code === 404 || body.error?.code === 410;

  if (isAbsent) {
    components.calendar = {
      state: 'verified',
      id: norm.calendarEventId
    };
  } else {
    allVerified = false;
    components.calendar = {
      state: statusCode === 200 ? 'uncertain' : 'failed',
      id: norm.calendarEventId,
      error: `Calendar event still present (HTTP ${statusCode})`
    };
  }
}

const verified = Boolean(allVerified && resources.length > 0);

return [{
  json: {
    ok: verified,
    verified,
    status: verified ? 'cancelled' : 'uncertain',
    state: verified ? 'cancelada' : 'incierta',
    resources,
    components,
    calendarEventId: norm.calendarEventId || null,
    zoomMeetingId: norm.zoomMeetingId || null
  }
}];
